<?php
if(!defined('ABSPATH'))exit;
class Terttus_Header_Widget extends \Elementor\Widget_Base{
 public function get_name(){return 'terttus_header';} public function get_title(){return 'Terttus Shop Header';} public function get_icon(){return 'eicon-site-logo';} public function get_categories(){return ['terttus-widgets'];}
 protected function register_controls(){$this->start_controls_section('c',['label'=>'Header']);$this->add_control('logo',['label'=>'Logo','type'=>\Elementor\Controls_Manager::MEDIA]);$this->add_control('shipping',['label'=>'Toptekst','type'=>\Elementor\Controls_Manager::TEXT,'default'=>'🚚 Fri fragt ved køb over 499 kr. · Levering 1–3 hverdage']);$this->add_control('menu',['label'=>'Menu shortcode/navn','type'=>\Elementor\Controls_Manager::TEXT,'default'=>'']);$this->end_controls_section();}
 protected function render(){$s=$this->get_settings_for_display();$cart=class_exists('WooCommerce')?wc_get_cart_url():'#';?><header class="tt-head"><div class="tt-top"><?php echo esc_html($s['shipping']);?></div><div class="tt-main"><a href="<?php echo esc_url(home_url('/'));?>" class="tt-logo"><?php if(!empty($s['logo']['url'])):?><img src="<?php echo esc_url($s['logo']['url']);?>" alt="<?php echo esc_attr(get_bloginfo('name'));?>"><?php else:?><strong>Terttus<span>.dk</span></strong><?php endif;?></a><form method="get" action="<?php echo esc_url(home_url('/'));?>"><input name="s" type="search" placeholder="Søg efter produkter..."><input type="hidden" name="post_type" value="product"><button>Søg</button></form><a class="tt-cart" href="<?php echo esc_url($cart);?>">🛒 Kurv<?php if(class_exists('WooCommerce')&&WC()->cart):?><b><?php echo (int)WC()->cart->get_cart_contents_count();?></b><?php endif;?></a></div><nav class="tt-nav"><?php wp_nav_menu(['theme_location'=>'primary','container'=>false,'fallback_cb'=>false]);?></nav></header><style>.tt-head{background:#fff;color:#10212d}.tt-top{text-align:center;background:#10212d;color:#fff;padding:9px 15px;font-size:14px}.tt-main{display:grid;grid-template-columns:140px 1fr auto;gap:20px;align-items:center;padding:16px 0}.tt-logo{text-decoration:none;font-size:26px;color:#087d82}.tt-logo span{color:#ff7b32}.tt-logo img{max-height:48px;max-width:140px}.tt-main form{display:flex;border:1px solid #d8e0e5;border-radius:11px;overflow:hidden}.tt-main input{border:0!important;box-shadow:none!important;flex:1;padding:12px 15px}.tt-main button{border:0;background:#148b93;color:#fff;padding:0 22px;font-weight:700}.tt-cart{position:relative;text-decoration:none;color:#10212d;font-weight:700;border:1px solid #dfe5e8;border-radius:11px;padding:12px 16px}.tt-cart b{position:absolute;right:-7px;top:-9px;background:#ff7b32;color:#fff;border-radius:50%;min-width:22px;height:22px;text-align:center;line-height:22px}.tt-nav ul{display:flex;gap:32px;list-style:none;margin:0;padding:12px 0;border-top:1px solid #edf0f2}.tt-nav a{text-decoration:none;color:#10212d;font-weight:700}@media(max-width:767px){.tt-main{grid-template-columns:1fr auto}.tt-main form{grid-column:1/-1;grid-row:2}.tt-nav{overflow-x:auto}.tt-nav ul{gap:20px;white-space:nowrap}}</style><?php }
}\Elementor\Plugin::instance()->widgets_manager->register(new Terttus_Header_Widget());